//! Runs the machine on fake hardware and prints every log line.
//! Usage: cargo run --example sim -- <run_ms> [EVENT ...]
//! The listed events are sent at t = 0, in order.

use posture::gen::fake::FakeHal;
use posture::gen::hal::SafeHal;
use posture::gen::machine::{Event, Machine};

fn main() {
    let args: Vec<String> = std::env::args().skip(1).collect();
    let run_ms: u64 = args.first().and_then(|a| a.parse().ok()).unwrap_or(15_000);
    let (fake, probe) = FakeHal::new();
    let mut hal = SafeHal::new(fake);
    let mut m = Machine::start(&mut hal);
    for name in args.iter().skip(1) {
        match Event::from_name(name) {
            Some(e) => {
                m.send(e, &mut hal);
            }
            None => eprintln!("unknown event {name}"),
        }
    }
    let mut printed = 0;
    let mut t = 0;
    while t <= run_ms {
        probe.borrow_mut().now_ms = t;
        m.tick(&mut hal);
        let p = probe.borrow();
        for (at, line) in p.logs.iter().skip(printed) {
            println!("{:>7.1}s  {line}", *at as f64 / 1000.0);
        }
        printed = p.logs.len();
        t += 10;
    }
    println!("final state: {}", m.state().id());
}
